"""Клиент для DeepSeek API с поддержкой Instructor для structured output."""
import json
import re
import time
import logging
from typing import Any, Dict, Optional

from django.conf import settings

logger = logging.getLogger(__name__)

DEFAULT_BASE_URL = getattr(settings, "AI_ASSISTANT_DEEPSEEK_BASE_URL", "https://api.deepseek.com/v1")
MODEL_CLASSIFICATION = getattr(settings, "AI_ASSISTANT_MODEL_CLASSIFICATION", "deepseek-chat")
MODEL_EXTRACTION = getattr(settings, "AI_ASSISTANT_MODEL_EXTRACTION", "deepseek-v4-flash")
MODEL_DEBUG = getattr(settings, "AI_ASSISTANT_MODEL_DEBUG", "deepseek-v4-pro")


def _parse_json(raw: str) -> Dict[str, Any]:
    """Парсит JSON из ответа LLM, обрабатывая markdown-обёртки (```json ... ```)."""
    if not raw:
        return {}
    text = raw.strip()
    m = re.search(r"```(?:json)?\s*\n?(.*?)\n?```", text, re.DOTALL)
    if m:
        text = m.group(1).strip()
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        return {"raw_response": text}


def _dict_to_pydantic_model(name: str, schema: dict):
    """Создаёт Pydantic модель из JSON Schema dict для Instructor."""
    from pydantic import BaseModel, create_model
    from typing import Optional as Opt, List

    type_map = {"string": str, "integer": int, "number": float, "boolean": bool}

    fields = {}
    for key, prop in schema.get("properties", {}).items():
        py_type = type_map.get(prop.get("type", "string"), str)
        fields[key] = (Opt[py_type], None)

    return create_model(name, **fields)


class DeepSeekClient:
    """Обёртка над OpenAI-совместимым DeepSeek API + Instructor."""

    def __init__(self, api_key: str, base_url: str = None):
        import openai
        self.api_key = api_key
        self.base_url = base_url or DEFAULT_BASE_URL
        self.raw_client = openai.OpenAI(api_key=api_key, base_url=self.base_url)

    def classify(self, prompt: str, temperature: float = 0.3, max_tokens: int = 500) -> dict:
        """Классификация — модель deepseek-chat."""
        return self._complete(prompt, MODEL_CLASSIFICATION, temperature, max_tokens)

    def extract_filters(self, prompt: str, temperature: float = 0.7, max_tokens: int = 2000) -> dict:
        """Извлечение фильтров — модель deepseek-v4-flash."""
        return self._complete(prompt, MODEL_EXTRACTION, temperature, max_tokens)

    def debug(self, prompt: str, temperature: float = 0.7, max_tokens: int = 4000) -> dict:
        """Отладка промптов — модель deepseek-v4-pro с reasoning."""
        return self._complete(prompt, MODEL_DEBUG, temperature, max_tokens)

    def structured_completion(
        self, prompt: str, response_schema: Optional[Dict[str, Any]] = None,
        temperature: float = 0.7, max_tokens: int = 2000,
    ) -> Dict[str, Any]:
        """Вызов с Instructor (Pydantic-модель из JSON Schema)."""
        model = MODEL_EXTRACTION
        messages = [
            {"role": "system", "content": "Ты полезный ассистент. Отвечай строго в формате JSON."},
            {"role": "user", "content": prompt},
        ]
        try:
            if response_schema:
                return self._run_instructor(model, messages, response_schema, temperature, max_tokens)
            return self._complete_basic(model, messages, temperature, max_tokens)
        except Exception as e:
            logger.error(f"DeepSeek API error: {e}")
            return {"error": str(e)}

    # ── приватные ─────────────────────────────────────────────────

    def _complete(self, prompt: str, model: str, temperature: float, max_tokens: int) -> dict:
        """Единый метод вызова: prompt → модель → parsed JSON + usage."""
        messages = [{"role": "user", "content": prompt}]
        start_time = time.monotonic()
        try:
            response = self.raw_client.chat.completions.create(
                model=model, messages=messages, temperature=temperature, max_tokens=max_tokens,
            )
        except Exception as e:
            logger.error(f"DeepSeek call failed: {e}")
            return {"error": str(e)}

        msg = response.choices[0].message
        usage = response.usage
        raw = msg.content or ""
        parsed = _parse_json(raw)

        return {
            "content": parsed,
            "raw_text": raw,
            "reasoning": getattr(msg, "reasoning_content", None),
            "prompt_tokens": usage.prompt_tokens if usage else 0,
            "completion_tokens": usage.completion_tokens if usage else 0,
            "reasoning_tokens": getattr(usage, "reasoning_tokens", None) if usage else 0,
            "total_tokens": usage.total_tokens if usage else 0,
            "model": response.model,
            "latency_ms": int((time.monotonic() - start_time) * 1000),
        }

    def _complete_basic(self, model, messages, temperature, max_tokens):
        return self._complete(messages[-1]["content"], model, temperature, max_tokens)

    def _run_instructor(self, model, messages, schema, temperature, max_tokens):
        import instructor
        pydantic_model = _dict_to_pydantic_model("ResponseModel", schema)
        client = instructor.from_openai(self.raw_client)
        resp = client.chat.completions.create(
            model=model, messages=messages, response_model=pydantic_model,
            temperature=temperature, max_tokens=max_tokens,
        )
        if hasattr(resp, "model_dump"):
            return resp.model_dump()
        if hasattr(resp, "dict"):
            return resp.dict()
        return resp

    def completion_with_reasoning(
        self, prompt: str, model: str = None, temperature: float = 0.7, max_tokens: int = 4000
    ) -> dict:
        """Совместимость со старым API. Использует MODEL_EXTRACTION по умолчанию."""
        model = model or MODEL_EXTRACTION
        return self._complete(prompt, model, temperature, max_tokens)


# глобальный singleton
_client: Optional[DeepSeekClient] = None


def get_deepseek_client(api_key: str = None, base_url: str = None) -> DeepSeekClient:
    """Возвращает singleton-клиент или создаёт новый с указанным ключом."""
    global _client
    if api_key and api_key != getattr(settings, "AI_ASSISTANT_DEEPSEEK_API_KEY", ""):
        return DeepSeekClient(api_key=api_key, base_url=base_url)
    if _client is None:
        api_key = api_key or getattr(settings, "AI_ASSISTANT_DEEPSEEK_API_KEY", "")
        _client = DeepSeekClient(api_key=api_key, base_url=base_url)
    return _client

